// A GRANTED third-party package (holds fs:read). It does real async work of its
// own via host timers — the case a naive "deny any single-principal deputy-class
// op" fix would FALSE-DENY. Two shapes:
//   readOwnViaTimer     — reads its OWN file in a timer callback. The scheduler
//                         (logger) equals the running principal, so the collected
//                         stack collapses to [logger] and the read is allowed.
//   readViaDeputyTimer  — drives the deputy DETACHED across a timer. Both
//                         principals in the causal chain (logger scheduler +
//                         deputy) are granted, so the deputy-class AND passes.
// @ref LLP 0013#phase-5 (ENG-22759)
var fs = require("fs");
var deputy = require("deputy-pkg");

function sleep(ms) {
  return new Promise(function (r) { setTimeout(r, ms); });
}

module.exports.readOwnViaTimer = async function readOwnViaTimer(path) {
  var out = "DENIED";
  setTimeout(function () {
    try {
      out = String(fs.readFileSync(path)).trim();
    } catch (_e) {
      out = "DENIED";
    }
  }, 0);
  await sleep(25);
  return out;
};

module.exports.readViaDeputyTimer = async function readViaDeputyTimer(path) {
  deputy.arm(path);
  setTimeout(deputy.readArmed, 0); // detached: only the deputy's frame at fire
  await sleep(25);
  var v = deputy.takeLast();
  return v ? v : "DENIED";
};
